//! Owner-local bounded tile cache. No network, background scan or area download.
use crate::Result;
use serde::{Deserialize,Serialize};use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,path::Path,time::{SystemTime,UNIX_EPOCH}};
const MAX:usize=64;const TILE:usize=262144;
#[derive(Clone,Serialize,Deserialize)]#[serde(deny_unknown_fields)]struct Entry{file:String,size:u64,stored:u64,expires:u64,used:u64,etag:String,modified:String,revalidate:bool}
#[derive(Default,Serialize,Deserialize)]#[serde(deny_unknown_fields)]struct Index{entries:BTreeMap<String,Entry>}
fn now()->u64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs()}
fn hex(b:&[u8])->String{b.iter().map(|b|format!("{b:02x}")).collect()}
fn load(root:&Path)->Result<Index>{let p=root.join("map-cache-v1.json");if !p.exists(){return Ok(Index::default())}let i:Index=serde_json::from_slice(&crate::sdk::read_bounded(&p,131072)?).map_err(|_|"Invalid map cache index")?;if i.entries.len()>MAX||i.entries.iter().any(|(k,e)|k.len()!=64||!k.bytes().all(|b|b.is_ascii_hexdigit())||!crate::valid_id(&e.file)||e.size>TILE as u64||e.etag.len()>512||e.modified.len()>512){return Err("Invalid map cache index".into())}Ok(i)}
fn save(root:&Path,i:&Index)->Result<()>{let b=serde_json::to_vec(i).map_err(|e|e.to_string())?;if crate::sdk::private_size(root,&root.join("map-cache-v1.json"))?+b.len()as u64>crate::sdk_storage::limits(root)?.documents{return Err("Private metadata quota reached".into())}crate::sdk::atomic(&root.join("map-cache-v1.json"),&b)}
fn remove(root:&Path,e:&Entry){let _=crate::sdk_storage::service(root,"blobs.delete",&json!({"id":e.file}));}
fn identity(publisher:&str,a:&Value)->Result<(String,Value,String)>{
 let n=&a["map"];crate::sdk_maps::validate(n)?;let z=n["zoom"].as_u64().unwrap();let world=1u64<<z;let x=a["x"].as_u64().filter(|v|*v<world).ok_or("Invalid tile column")?;let y=a["y"].as_u64().filter(|v|*v<world).ok_or("Invalid tile row")?;
 let lat=n["latitude"].as_f64().unwrap().to_radians();let cx=(n["longitude"].as_f64().unwrap()+180.).rem_euclid(360.)/360.*world as f64;let cy=(1.-(lat.tan()+1./lat.cos()).ln()/std::f64::consts::PI)/2.*world as f64;
 let dx=(x as f64+0.5-cx+world as f64/2.).rem_euclid(world as f64)-world as f64/2.;if dx.abs()>2.5||(y as f64+0.5-cy).abs()>2.5{return Err("Only the bounded current viewport may request a tile".into())}
 let p=&n["provider"];let url=p["template"].as_str().unwrap().replace("{z}",&z.to_string()).replace("{x}",&x.to_string()).replace("{y}",&y.to_string());let key=hex(&Sha256::digest(format!("{publisher}\n{p}\n{z}/{x}/{y}")));
 Ok((key,p.clone(),url))
}
fn header(h:&Value,k:&str)->String{h[k].as_str().filter(|s|s.len()<=512&&s.bytes().all(|b|(32..=126).contains(&b))).unwrap_or("").to_string()}
// Strict IMF-fixdate parser; unsupported/invalid dates are stale, never guessed fresh.
fn date(s:&str)->Option<u64>{let p:Vec<_>=s.split_whitespace().collect();if p.len()!=6||p[5]!="GMT"||!p[0].ends_with(','){return None}let d=p[1].parse::<i64>().ok()?;let m=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"].iter().position(|v|*v==p[2])?as i64+1;let year=p[3].parse::<i64>().ok()?;if !(1970..=2200).contains(&year){return None}let leap=year%4==0&&(year%100!=0||year%400==0);let days=[31,if leap{29}else{28},31,30,31,30,31,31,30,31,30,31];if d<1||d>days[m as usize-1]{return None}let t:Vec<_>=p[4].split(':').map(str::parse::<i64>).collect::<std::result::Result<_,_>>().ok()?;if t.len()!=3||!(0..24).contains(&t[0])||!(0..60).contains(&t[1])||!(0..60).contains(&t[2]){return None}let y=year-i64::from(m<=2);let era=y.div_euclid(400);let yo=y-era*400;let mp=m+if m>2{-3}else{9};let doy=(153*mp+2)/5+d-1;let days=era*146097+yo*365+yo/4-yo/100+doy-719468;u64::try_from(days*86400+t[0]*3600+t[1]*60+t[2]).ok()}
fn policy(h:&Value,url:&str,t:u64)->(u64,bool,bool){
 let cc=header(h,"cache-control").to_ascii_lowercase();let directives:Vec<_>=cc.split(',').map(str::trim).collect();let no_store=directives.contains(&"no-store");let revalidate=directives.iter().any(|d|["no-cache","must-revalidate"].contains(d)||d.starts_with("no-cache="));
 let age=header(h,"age").parse::<u64>().unwrap_or(0).max(date(&header(h,"date")).map(|d|t.saturating_sub(d)).unwrap_or(0));
 let ages:Vec<_>=directives.iter().filter(|d|d.starts_with("max-age")).map(|d|d.strip_prefix("max-age=").and_then(|v|v.trim_matches('"').parse::<u64>().ok()).unwrap_or(0)).collect();let max_age=ages.into_iter().min();
 let ttl=max_age.or_else(||date(&header(h,"expires")).map(|e|e.saturating_sub(date(&header(h,"date")).unwrap_or(t))))
 .unwrap_or(if url.starts_with("https://tile.openstreetmap.org/"){604800}else{0}).min(604800).saturating_sub(age);
 (if directives.iter().any(|d|*d=="no-cache"||d.starts_with("no-cache=")){0}else{ttl},no_store,revalidate)
}
pub(crate) fn service(root:&Path,publisher:&str,service:&str,a:&Value)->Result<Value>{at(root,publisher,service,a,now())}
fn at(root:&Path,publisher:&str,service:&str,a:&Value,t:u64)->Result<Value>{
 if service=="maps.cache.viewport"{let n=&a["map"];crate::sdk_maps::validate(n)?;let width=a["width"].as_u64().filter(|n|*n>0&&*n<=1024).ok_or("Map viewport width must be1–1024 logical pixels")?;let height=a["height"].as_u64().filter(|n|*n>0&&*n<=1024).ok_or("Map viewport height must be1–1024 logical pixels")?;let z=n["zoom"].as_u64().unwrap();let world=(1u64<<z)as f64;let cx=(n["longitude"].as_f64().unwrap()+180.).rem_euclid(360.)/360.*world;let lat=n["latitude"].as_f64().unwrap().to_radians();let cy=(1.-(lat.tan()+1./lat.cos()).ln()/std::f64::consts::PI)/2.*world;let mut seen=std::collections::BTreeSet::new();let mut tiles=Vec::new();for y in ((cy-height as f64/512.).floor()as i64)..=((cy+height as f64/512.-1e-9).floor()as i64){if y<0||y>=world as i64{continue}for x in ((cx-width as f64/512.).floor()as i64)..=((cx+width as f64/512.-1e-9).floor()as i64){let x=x.rem_euclid(world as i64)as u64;if !seen.insert((x,y)){continue}if seen.len()>25{return Err("Map viewport exceeds25 tiles".into())}let mut lookup=a.clone();lookup["x"]=json!(x);lookup["y"]=json!(y);let value=at(root,publisher,"maps.cache.lookup",&lookup,t)?;tiles.push(json!({"x":x,"y":y,"value":value}));}}return Ok(json!({"tiles":tiles}))}
 let mut i=load(root)?;
 if service=="maps.cache.clear"{let old=i.entries.values().cloned().collect::<Vec<_>>();i.entries.clear();save(root,&i)?;for e in old{remove(root,&e)}return Ok(json!({"cleared":true}))}
 let(key,p,url)=identity(publisher,a)?;
 if service=="maps.cache.lookup"{
  let offline=a["offline"].as_bool().unwrap_or(false);if offline&&p["offline_allowed"]!=true{return Err("This provider does not permit offline map use".into())}
  let mut headers=json!({});let mut value=json!({"hit":false,"stale":false});
  if let Some(e)=i.entries.get_mut(&key){
   if crate::sdk_storage::resolve(root,&e.file).is_ok(){let stale=t<e.stored||t>=e.expires;e.used=t;if !e.etag.is_empty(){headers["If-None-Match"]=json!(e.etag)}if !e.modified.is_empty(){headers["If-Modified-Since"]=json!(e.modified)}
    if !stale||offline&&!e.revalidate{value=json!({"hit":true,"file":e.file,"stale":stale,"stored":e.stored,"expires":e.expires});}
   }else{i.entries.remove(&key);}
  }
  save(root,&i)?;if !offline{value["request"]=json!({"url":url,"method":"GET","response":"hex","headers":headers})}else if value["hit"]!=true{value["unavailable"]=json!(true)}return Ok(value)
 }
 if service!="maps.cache.store"{return Err("Unsupported map cache service".into())}
 let r=&a["response"];crate::sdk_http::reply(r)?;let status=r["status"].as_u64().unwrap();let h=&r["headers"];let(ttl,no_store,revalidate)=policy(h,&url,t);
 if no_store{if let Some(old)=i.entries.remove(&key){save(root,&i)?;remove(root,&old)}return Ok(json!({"stored":false,"reason":"no-store"}))}
 if status==304{let e=i.entries.get_mut(&key).ok_or("304 without a cached tile")?;crate::sdk_storage::resolve(root,&e.file)?;let ttl=if h.get("cache-control").is_none()&&h.get("expires").is_none(){e.expires.saturating_sub(e.stored)}else{ttl};e.stored=t;e.expires=t.saturating_add(ttl);e.used=t;e.revalidate|=revalidate;let etag=header(h,"etag");if !etag.is_empty(){e.etag=etag}let modified=header(h,"last-modified");if !modified.is_empty(){e.modified=modified}let result=json!({"stored":true,"file":e.file,"stale":ttl==0});save(root,&i)?;return Ok(result)}
 if status!=200{return Err("Tile provider returned a non-success status; old cache retained".into())}
 let mime=header(h,"content-type").split(';').next().unwrap_or("").trim().to_ascii_lowercase();if !["image/png","image/jpeg"].contains(&mime.as_str()){return Err("Tile provider did not return PNG/JPEG".into())}
 let encoded=r["hex"].as_str().ok_or("Missing binary tile response")?;if encoded.is_empty()||encoded.len()>TILE*2||encoded.len()%2!=0{return Err("Tile exceeds256KiB".into())}let bytes=encoded.as_bytes().chunks_exact(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).map_err(|_|"Invalid tile bytes")?,16).map_err(|_|"Invalid tile bytes")).collect::<std::result::Result<Vec<_>,_>>()?;
 // Encoded PNG dimensions checked before caching; JPEG is checked by bounded native decoder.
 if mime=="image/png"&&(bytes.len()<24||&bytes[..8]!=b"\x89PNG\r\n\x1a\n"||&bytes[12..16]!=b"IHDR"||u32::from_be_bytes(bytes[16..20].try_into().unwrap())!=256||u32::from_be_bytes(bytes[20..24].try_into().unwrap())!=256){return Err("Map tiles must be256×256".into())}
 if mime=="image/jpeg"&&!bytes.starts_with(&[255,216,255]){return Err("Invalid JPEG tile".into())}
 let created=crate::sdk_storage::service(root,"blobs.begin",&json!({"name":"Map tile","mime":mime,"cache":true}))?;let id=created["id"].as_str().unwrap().to_string();
 let result=(||{for(n,b)in bytes.chunks(65536).enumerate(){crate::sdk_storage::service(root,"blobs.append",&json!({"id":id,"offset":n*65536,"hex":hex(b)}))?;}crate::sdk_storage::service(root,"blobs.finish",&json!({"id":id}))?;
 let mut discard=Vec::new();if let Some(old)=i.entries.insert(key,Entry{file:id.clone(),size:bytes.len()as u64,stored:t,expires:t.saturating_add(ttl),used:t,etag:header(h,"etag"),modified:header(h,"last-modified"),revalidate}){discard.push(old)}
 while i.entries.len()>MAX{let old=i.entries.iter().min_by_key(|(_,e)|e.used).unwrap().0.clone();discard.push(i.entries.remove(&old).unwrap());}save(root,&i)?;for old in discard{remove(root,&old)}Ok(json!({"stored":true,"file":id,"stale":ttl==0,"expires":t.saturating_add(ttl)}))})();if result.is_err(){let _=crate::sdk_storage::service(root,"blobs.delete",&json!({"id":id}));}result
}
#[cfg(test)]mod tests{
 use super::*;
 fn args()->Value{json!({"map":{"provider":{"id":"demo","name":"Demo","data":"other","attribution":"Demo","copyright_url":"https://example.org/license","template":"https://example.org/{z}/{x}/{y}.png","offline_allowed":true},"latitude":0.,"longitude":0.,"zoom":1,"tiles":[],"markers":[]},"x":0,"y":0})}
 fn response()->Value{json!({"status":200,"hex":hex(include_bytes!("../../docs/fixtures/maps/1-0-0.png")),"headers":{"content-type":"image/png","cache-control":"max-age=60","etag":"\"one\""}})}
 #[test]fn wrap_viewport_cache_wraps_and_deduplicates_world_edges(){let d=tempfile::tempdir().unwrap();let mut a=args();a["width"]=json!(1024);a["height"]=json!(1024);let v=at(d.path(),"pub","maps.cache.viewport",&a,100).unwrap();assert_eq!(v["tiles"].as_array().unwrap().len(),4);a["map"]["zoom"]=json!(5);a["map"]["longitude"]=json!(11.);let v=at(d.path(),"pub","maps.cache.viewport",&a,100).unwrap();assert!(v["tiles"].as_array().unwrap().len()<=25);a["width"]=json!(1025);assert!(at(d.path(),"pub","maps.cache.viewport",&a,100).is_err());}
 #[test]fn map_cache_hit_stale_offline_conditional_and_publisher_isolation(){let d=tempfile::tempdir().unwrap();let mut a=args();a["response"]=response();at(d.path(),"pub","maps.cache.store",&a,100).unwrap();let fresh=at(d.path(),"pub","maps.cache.lookup",&a,110).unwrap();assert_eq!(fresh["hit"],true);assert_eq!(at(d.path(),"other","maps.cache.lookup",&a,110).unwrap()["hit"],false);let stale=at(d.path(),"pub","maps.cache.lookup",&a,170).unwrap();assert_eq!(stale["hit"],false);assert_eq!(stale["request"]["headers"]["If-None-Match"],"\"one\"");a["offline"]=json!(true);assert_eq!(at(d.path(),"pub","maps.cache.lookup",&a,170).unwrap()["stale"],true);a["response"]=json!({"status":304,"hex":"","headers":{"cache-control":"max-age=120"}});at(d.path(),"pub","maps.cache.store",&a,170).unwrap();assert_eq!(at(d.path(),"pub","maps.cache.lookup",&a,180).unwrap()["stale"],false);}
 #[test]fn map_cache_no_store_must_revalidate_and_invalid_data_fail_closed(){let d=tempfile::tempdir().unwrap();let mut a=args();a["response"]=response();a["response"]["headers"]["cache-control"]=json!("no-cache, must-revalidate");at(d.path(),"pub","maps.cache.store",&a,100).unwrap();a["offline"]=json!(true);assert_eq!(at(d.path(),"pub","maps.cache.lookup",&a,101).unwrap()["unavailable"],true);a["response"]["headers"]["cache-control"]=json!("no-store");assert_eq!(at(d.path(),"pub","maps.cache.store",&a,102).unwrap()["stored"],false);assert_eq!(load(d.path()).unwrap().entries.len(),0);a["response"]=response();a["response"]["hex"]=json!("00");assert!(at(d.path(),"pub","maps.cache.store",&a,100).is_err());a["map"]["provider"]["offline_allowed"]=json!(false);assert!(at(d.path(),"pub","maps.cache.lookup",&a,100).is_err());}
 #[test]fn map_cache_expiry_age_dates_and_clock_rollback_are_conservative(){let t=1445412480;assert_eq!(date("Wed, 21 Oct 2015 07:28:00 GMT"),Some(t));assert_eq!(date("Wed, 31 Feb 2015 07:28:00 GMT"),None);assert_eq!(policy(&json!({"cache-control":"max-age=100","age":"80"}),"https://example.org/",t).0,20);assert_eq!(policy(&json!({"date":"Wed, 21 Oct 2015 07:28:00 GMT","expires":"Wed, 21 Oct 2015 07:29:00 GMT"}),"https://example.org/",t).0,60);let d=tempfile::tempdir().unwrap();let mut a=args();a["response"]=response();at(d.path(),"p","maps.cache.store",&a,100).unwrap();assert_eq!(at(d.path(),"p","maps.cache.lookup",&a,90).unwrap()["hit"],false);}
 #[test]fn map_cache_eviction_missing_blobs_and_clear_preserve_other_private_files(){let d=tempfile::tempdir().unwrap();let other=crate::sdk_storage::save_bytes(d.path(),"Keep","text/plain",b"keep").unwrap();let mut a=args();a["response"]=response();for n in 0..65{a["map"]["provider"]["id"]=json!(format!("p{n}"));at(d.path(),"p","maps.cache.store",&a,n+100).unwrap();}assert_eq!(load(d.path()).unwrap().entries.len(),64);let hit=at(d.path(),"p","maps.cache.lookup",&a,165).unwrap();crate::sdk_storage::service(d.path(),"blobs.delete",&json!({"id":hit["file"]})).unwrap();assert_eq!(at(d.path(),"p","maps.cache.lookup",&a,166).unwrap()["hit"],false);at(d.path(),"p","maps.cache.clear",&json!({}),170).unwrap();assert_eq!(crate::sdk_storage::read_all(d.path(),other["id"].as_str().unwrap(),20).unwrap(),b"keep");}
}
